import { Response, NextFunction } from 'express';
import { AuthenticatedRequest } from '../types.js';
import { getSupabaseClient, isRealSupabaseConfigured } from '../services/supabase.js';

export const authMiddleware = async (
  req: AuthenticatedRequest,
  res: Response,
  next: NextFunction
): Promise<void> => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or malformed Authorization header' });
    return;
  }

  const token = authHeader.split(' ')[1];

  if (!token) {
    res.status(401).json({ error: 'Authorization token not provided' });
    return;
  }

  // If real Supabase is configured, verify with Supabase Auth
  if (isRealSupabaseConfigured()) {
    try {
      const supabase = getSupabaseClient();
      const { data: { user }, error } = await supabase.auth.getUser(token);

      if (error || !user) {
        res.status(401).json({ error: 'Invalid or expired authorization token' });
        return;
      }

      req.user = {
        id: user.id,
        email: user.email || '',
      };
      next();
      return;
    } catch (err: any) {
      res.status(401).json({ error: 'Authentication verification failed', details: err.message });
      return;
    }
  }

  // Development/Demo fallback mode when live Supabase credentials aren't set
  if (token === 'invalid-token') {
    res.status(401).json({ error: 'Invalid authorization token' });
    return;
  }

  // Accept valid demo tokens or simulate JWT payload
  req.user = {
    id: 'usr_demo_123',
    email: 'demo@pingwatch.test',
  };
  next();
};
